/* Building a linked list, then tearing it down.
   Each malloc appears as a heap block; each `next` is an arrow. After free()
   the block disappears and any pointer still aimed at it turns red. */
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int          value;
    struct Node *next;
} Node;

Node *push_front(Node *head, int value) {
    Node *n = malloc(sizeof(Node));
    n->value = value;
    n->next  = head;
    return n;
}

int sum(Node *head) {
    int total = 0;
    for (Node *p = head; p != NULL; p = p->next)
        total += p->value;
    return total;
}

int main(void) {
    Node *head = NULL;

    for (int i = 1; i <= 4; i++)
        head = push_front(head, i * 10);

    printf("sum = %d\n", sum(head));

    while (head != NULL) {
        Node *doomed = head;
        head = head->next;
        free(doomed);
        /* `doomed` is now dangling -- it still points at freed memory */
    }

    printf("list emptied\n");
    return 0;
}
